public str getName()
{
    return fieldPName(InventDim, InventDimension9);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventDimension9 from inventDim
        group by InventDimension9
    {
        ret.add(inventDim.InventDimension9);
    }
    return ret;
}

